"""Admission (capacity + deficient cut) and schedule compilation."""
from collections import defaultdict, deque
from cutcheck import find_deficient_cut
from maxflow import Dinic


# ------------------------------------------------------------------ admission
def capacity_denial(svc, pid, s, e, env):
    ticks = set([s])
    for b in svc.bookings.values():
        if b.live and s < b.s < e:
            ticks.add(b.s)
    for t in sorted(ticks):
        for l, bl in env.items():
            used = svc.used_at(l, t)
            if used + bl > svc.caps[l]:
                return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                        'kind': 'capacity', 'link': l, 'time': t,
                        'used': used + bl, 'capacity': svc.caps[l]}
    return None


def compile_prepare(svc, pid, s, e, period, parts, env):
    cert = capacity_denial(svc, pid, s, e, env)
    if cert is not None:
        return cert
    caps = [period * env.get(l, 0) for l in range(len(svc.links))]
    r = dict(parts)
    cut = find_deficient_cut(svc.n, svc.links, caps, parts, r)
    if cut is not None:
        return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                'kind': 'cut', 'cut': cut}
    plan = build_plan(svc.n, svc.links, caps, parts, r)
    if plan is None:
        return {'status': 'denied', 'id': pid, 'rev': svc.rev,
                'kind': 'cut', 'cut': _fallback_cut(svc.n, svc.links, caps,
                                                   parts, r)}
    return {'status': 'prepared', 'id': pid, 'rev': svc.rev, 'plan': plan}


def _fallback_cut(n, links, caps, parts, r):
    cut = find_deficient_cut(n, links, caps, parts, r)
    if cut is not None:
        return cut
    return [parts[0][0]]


# ------------------------------------------------------------------ router
class Router(object):
    def __init__(self, n, links, caps):
        self.n = n
        self.links = links
        m = len(links)
        self.res = [caps[a // 2] for a in range(2 * m)]
        self.tail = [links[a // 2][0] if a % 2 == 0 else links[a // 2][1]
                     for a in range(2 * m)]
        self.head = [links[a // 2][1] if a % 2 == 0 else links[a // 2][0]
                     for a in range(2 * m)]

    def clone(self):
        r = Router.__new__(Router)
        r.n = self.n
        r.links = self.links
        r.res = list(self.res)
        r.tail = self.tail
        r.head = self.head
        return r

    def route(self, src, dst, amount, allowed):
        """Route `amount` units src->dst over vertices in `allowed`.

        Returns a list of (path(list of arc ids), amount) or None.
        """
        if amount == 0:
            return []
        verts = sorted(allowed)
        idx = {v: i for i, v in enumerate(verts)}
        if src not in idx or dst not in idx:
            return None
        g = Dinic(len(verts) + 2)
        S = len(verts)
        T = S + 1
        arcs = []
        for a in range(len(self.res)):
            if (self.res[a] > 0 and self.tail[a] in idx
                    and self.head[a] in idx):
                arcs.append((a, g.add(idx[self.tail[a]], idx[self.head[a]],
                                      self.res[a])))
        g.add(S, idx[src], amount)
        g.add(idx[dst], T, amount)
        got = g.maxflow(S, T)
        if got != amount:
            return None
        flowmap = {}
        for (a, i) in arcs:
            f = self.res[a] - g.cap[i]
            if f > 0:
                flowmap[a] = f
                self.res[a] -= f
        return _decompose(src, dst, flowmap, amount, self.tail, self.head)


def _decompose(src, dst, flowmap, amount, tail, head):
    out = []
    remaining = dict(flowmap)
    outadj = defaultdict(list)
    for a, amt in remaining.items():
        if amt > 0:
            outadj[tail[a]].append(a)
    while amount > 0:
        stack = [src]
        prev = {src: None}
        found = False
        while stack:
            x = stack.pop()
            if x == dst:
                found = True
                break
            for a in outadj[x]:
                if remaining.get(a, 0) <= 0:
                    continue
                y = head[a]
                if y in prev:
                    continue
                prev[y] = a
                stack.append(y)
        if not found:
            return None
        path = []
        x = dst
        while prev[x] is not None:
            a = prev[x]
            path.append(a)
            x = tail[a]
        path.reverse()
        bottleneck = min(remaining[a] for a in path)
        for a in path:
            remaining[a] -= bottleneck
        out.append((path, bottleneck))
        amount -= bottleneck
    if amount != 0:
        return None
    return out


# ------------------------------------------------------------------ distances
def participant_distance(n, links, parts):
    """dist[(u,w)] = hop length of the shortest u->w path whose internal
    vertices are not participants (inf when none)."""
    C = set([v for (v, _rv) in parts])
    dist = {}
    for (u, _ru) in parts:
        # BFS from u over non-participant internal vertices
        seen = {u: 0}
        q = deque([u])
        adj = defaultdict(list)
        for l, (a, b) in enumerate(links):
            adj[a].append((b, 2 * l))
            adj[b].append((a, 2 * l + 1))
        while q:
            x = q.popleft()
            if x in C and x != u:
                continue
            for (y, a) in adj[x]:
                if y not in seen:
                    seen[y] = seen[x] + 1
                    q.append(y)
        for (w, _rw) in parts:
            dist[(u, w)] = seen.get(w, float('inf'))
    return dist


# ------------------------------------------------------------------ plan build
def build_plan(n, links, caps, parts, r):
    D = sum(r.values())
    if D <= 0:
        return None
    dist = participant_distance(n, links, parts)
    for strat in ('bfs', 'star', 'chain'):
        trees = _make_trees(strat, parts, dist)
        if trees is None:
            continue
        plan = _route_trees(n, links, caps, parts, r, trees)
        if plan is not None:
            return plan
    return None


def _make_trees(strat, parts, dist):
    trees = []
    C = [v for (v, rv) in parts]
    for (v, rv) in parts:
        if rv <= 0:
            continue
        if strat == 'star':
            edges = [[v, w] for w in C if w != v]
        elif strat == 'bfs':
            order = sorted([w for w in C if w != v],
                           key=lambda w: (dist[(v, w)], w))
            placed = set([v])
            edges = []
            parents = {v: None}
            for w in order:
                best = None
                for u in placed:
                    d = dist[(u, w)]
                    if d == float('inf'):
                        continue
                    if best is None or d < best[0]:
                        best = (d, u)
                if best is None:
                    return None
                edges.append([best[1], w])
                parents[w] = best[1]
                placed.add(w)
        else:  # chain
            edges = []
            prev = None
            for w in C:
                if w == v:
                    prev = v
                    continue
                if prev is None:
                    return None
                edges.append([prev, w])
                prev = w
        trees.append([v, rv, edges])
    return trees


def _route_trees(n, links, caps, parts, r, trees):
    C = set([v for (v, _rv) in parts])
    L = defaultdict(int)
    for (root, cnt, edges) in trees:
        for (u, w) in edges:
            L[(u, w)] += cnt
    if not L:
        return {'trees': trees, 'routes': [], 'recipes': []}
    router = Router(n, links, caps)
    routes = []
    recipes = []
    memo = {}
    order = sorted(L.items(), key=lambda kv: -kv[1])
    for ((u, w), amt) in order:
        allowed = set(range(n)) - (C - set([u, w]))
        fl = router.route(u, w, amt, allowed)
        if fl is None:
            return None
        for (path, cnt) in fl:
            rid = _recipe(path, recipes, memo)
            if rid is None:
                return None
            routes.append([u, w, cnt, rid])
    return {'trees': trees, 'routes': routes, 'recipes': recipes}


def _recipe(path, recipes, memo):
    if not path:
        return None
    node = None
    for a in path:
        single = (0, a // 2, a % 2)
        if single not in memo:
            memo[single] = len(recipes)
            recipes.append([0, a // 2, a % 2])
        cur = memo[single]
        if node is None:
            node = cur
        else:
            key = (node, cur)
            if key not in memo:
                memo[key] = len(recipes)
                recipes.append([1, node, cur])
            node = memo[key]
    return node
